                      </div>

                      <div className="relative flex items-center"><div className="flex-grow border-t border-gray-600"></div><span className="flex-shrink mx-4 text-gray-500 text-xs font-bold">OR</span><div className="flex-grow border-t border-gray-600"></div></div>

                      {/* METHOD 3: URLs */}
                      <div className={`p-4 border rounded-lg transition-all ${isUrlMode ? 'border-blue-500/50 bg-gray-800' : 'border-gray-700 opacity-60'}`}>
                        <p className="font-semibold text-white mb-3 flex items-center"><LinkIcon className="w-4 h-4 mr-2"/> Extract from URLs</p>
                        <div>
                          <textarea id="urls" rows={3} value={urls} onChange={(e) => setUrls(e.target.value)} placeholder="https://example.com" className="w-full px-3 py-2 bg-gray-700 border border-gray-600 rounded-md focus:ring-2 focus:ring-blue-500 transition resize-y text-sm" disabled={isLoading}/>
                          <button
                            onClick={handleExtract}
                            disabled={isLoading || !isUrlMode}
                            className="w-full mt-3 py-2 px-4 text-sm font-bold rounded-md bg-indigo-600 hover:bg-indigo-700 text-white shadow-lg transition-all disabled:opacity-50 disabled:cursor-not-allowed"
                          >
                            Extract from URLs
                          </button>
                        </div>
                      </div>

                      {isLoading && (
                            <button onClick={handleStopSearch} className="w-full flex items-center justify-center py-2 px-4 text-sm font-bold rounded-md bg-red-600/80 hover:bg-red-600 text-white shadow-lg transition-all border border-red-500">
                              <XCircleIcon className="w-4 h-4 mr-2" /> Stop Search
                            </button>
                      )}
                    </div>
                  </div>

                  {/* EXTRACTOR RESULTS */}
                  <div className="lg:col-span-9">
                    <ResultsDisplay results={results} isLoading={isLoading} error={error} progressMessage={progressMessage} onClearResults={handleClear} />
                  </div>
                </div>
              );
      }
  }

  return (
