import React, { useState, useRef } from 'react';
import DocumentArrowUpIcon from './icons/DocumentArrowUpIcon';
import FolderOpenIcon from './icons/FolderOpenIcon';
import ArrowPathIcon from './icons/ArrowPathIcon';
import ShieldCheckIcon from './icons/ShieldCheckIcon';
import XCircleIcon from './icons/XCircleIcon';
import CheckIcon from './icons/CheckIcon';
import PauseIcon from './icons/PauseIcon';
import PlayIcon from './icons/PlayIcon';
import StopIcon from './icons/StopIcon';
import ToggleSwitch from './ToggleSwitch';
import JSZip from 'jszip';
import { GoogleGenAI, Type } from "@google/genai";

interface EmailValidatorProps {
  showToast: (msg: string) => void;
}

interface ValidationResult {
  category: 'Professional' | 'Public' | 'Gov/Edu' | 'Financial' | 'Disposable' | 'Invalid';
  emails: string[];
}

const PUBLIC_DOMAINS = new Set([
  'gmail.com', 'googlemail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'live.com', 'msn.com',
  'aol.com', 'icloud.com', 'me.com', 'protonmail.com', 'zoho.com', 'yandex.com', 'mail.com', 'gmx.com'
]);

const DISPOSABLE_DOMAINS = new Set([
  'temp-mail.org', 'guerrillamail.com', '10minutemail.com', 'mailinator.com', 'sharklasers.com'
]);

const FINANCIAL_KEYWORDS = ['bank', 'credit', 'capital', 'finance', 'invest', 'trading', 'wealth', 'pay', 'crypto', 'wallet'];

const EmailValidator: React.FC<EmailValidatorProps> = ({ showToast }) => {
  const [inputText, setInputText] = useState('');
  const [results, setResults] = useState<ValidationResult[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [useOnlineMode, setUseOnlineMode] = useState(false);
  const [progress, setProgress] = useState<{ current: number; total: number } | null>(null);

  const controlRef = useRef({ shouldStop: false, isPaused: false });

  const classifyEmailOffline = (email: string): ValidationResult['category'] => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) return 'Invalid';

    const [user, domain] = email.toLowerCase().split('@');
    const parts = domain.split('.');
    const tld = parts[parts.length - 1];

    if (DISPOSABLE_DOMAINS.has(domain)) return 'Disposable';
    if (PUBLIC_DOMAINS.has(domain)) return 'Public';
    if (tld === 'gov' || tld === 'edu' || domain.includes('.edu.') || domain.includes('.gov.')) return 'Gov/Edu';
    if (FINANCIAL_KEYWORDS.some(kw => domain.includes(kw))) return 'Financial';

    // Heuristic for "Fake" usernames: high number count or random chars
    const numCount = (user.match(/\d/g) || []).length;
    if (numCount > 5 || user.length > 15 && !user.includes('.') && !user.includes('_')) {
        // We could put these in "Disposable" or "Invalid", but for this tool let's call it professional unless TLD is weird
    }

    return 'Professional';
  };

  const classifyDomainsOnline = async (domains: string[]): Promise<Map<string, ValidationResult['category']>> => {
    const apiKey = localStorage.getItem('gemini_api_key') || process.env.API_KEY;
    if (!apiKey) throw new Error("API Key missing");

    const ai = new GoogleGenAI({ apiKey });
    const prompt = `Classify these business domains into categories: Professional, Gov/Edu, or Financial. 
    Professional: standard corporate domains.
    Gov/Edu: Government or Educational institutions.
    Financial: Banks, Investment firms.

    Domains: ${domains.join(', ')}

    Return ONLY a JSON object where keys are domains and values are the categories.`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          description: "Map of domain to category",
          properties: domains.reduce((acc: any, d) => {
            acc[d] = { type: Type.STRING };
            return acc;
          }, {})
        }
      }
    });

    try {
        const data = JSON.parse(response.text || '{}');
        const map = new Map<string, ValidationResult['category']>();
        Object.entries(data).forEach(([d, cat]) => {
            map.set(d, cat as ValidationResult['category']);
        });
        return map;
    } catch (e) {
        console.error("Online classification failed", e);
        return new Map();
    }
  };

  const processEmails = async () => {
    if (!inputText.trim()) {
      showToast("Please enter emails to process.");
      return;
    }

    setIsProcessing(true);
    setIsPaused(false);
    controlRef.current = { shouldStop: false, isPaused: false };

    const rawEmails = inputText.split(/[\s,;]+/).map(e => e.trim()).filter(Boolean);
    const uniqueEmails = Array.from(new Set(rawEmails));
    const total = uniqueEmails.length;

    const categoryMap: Record<ValidationResult['category'], string[]> = {
      Professional: [], Public: [], 'Gov/Edu': [], Financial: [], Disposable: [], Invalid: []
    };

    const needsOnline: string[] = [];
    const domainToEmails = new Map<string, string[]>();

    // Phase 1: Offline Classification
    uniqueEmails.forEach(email => {
      const cat = classifyEmailOffline(email);
      if (useOnlineMode && cat === 'Professional') {
          const domain = email.split('@')[1]?.toLowerCase();
          if (domain) {
              if (!domainToEmails.has(domain)) {
                  domainToEmails.set(domain, []);
                  needsOnline.push(domain);
              }
              domainToEmails.get(domain)!.push(email);
          }
      } else {
          categoryMap[cat].push(email);
      }
    });

    // Phase 2: Online Classification (Batched)
    if (useOnlineMode && needsOnline.length > 0) {
        const BATCH_SIZE = 30;
        for (let i = 0; i < needsOnline.length; i += BATCH_SIZE) {
            if (controlRef.current.shouldStop) break;
            while (controlRef.current.isPaused) await new Promise(r => setTimeout(r, 200));

            const batch = needsOnline.slice(i, i + BATCH_SIZE);
            setProgress({ current: i, total: needsOnline.length });

            try {
                const onlineResults = await classifyDomainsOnline(batch);
                batch.forEach(domain => {
                    const cat = onlineResults.get(domain) || 'Professional';
                    const emails = domainToEmails.get(domain) || [];
                    if (categoryMap[cat]) categoryMap[cat].push(...emails);
                    else categoryMap['Professional'].push(...emails);
                });
            } catch (e) {
                batch.forEach(domain => {
                    categoryMap['Professional'].push(...(domainToEmails.get(domain) || []));
                });
            }
        }
    }

    setResults(Object.entries(categoryMap).map(([category, emails]) => ({
      category: category as ValidationResult['category'],
      emails
    })));

    setIsProcessing(false);
    setProgress(null);
    showToast(`Validation complete. ${uniqueEmails.length} emails sorted.`);
  };

  const handleExportZip = async () => {
    const zip = new JSZip();
    results.forEach(res => {
      if (res.emails.length > 0) {
        zip.file(`${res.category.replace('/', '_')}_Emails.txt`, res.emails.join('\n'));
      }
    });
    const blob = await zip.generateAsync({ type: 'blob' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Validated_Emails_${new Date().getTime()}.zip`;
    a.click();
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 h-full">
      <div className="lg:col-span-4 flex flex-col h-full space-y-4">
        <div className="bg-gray-800/50 backdrop-blur-sm border border-gray-700 rounded-xl shadow-2xl p-6 flex-grow flex flex-col">
          <div className="mb-4">
            <h2 className="text-2xl font-bold text-white flex items-center gap-2">
              <ShieldCheckIcon className="w-6 h-6 text-blue-400" />
              Sorter & Validator
            </h2>
            <div className="mt-4 space-y-2">
                <ToggleSwitch 
                  label="AI Enhancement (Online)" 
                  enabled={useOnlineMode} 
                  onChange={setUseOnlineMode} 
                  disabled={isProcessing}
                />
                <p className="text-gray-400 text-xs">
                  {useOnlineMode 
                    ? "Deep classification of business vs. finance vs. gov using AI." 
                    : "Fast regex/list-based sorting. Zero API cost."}
                </p>
            </div>
          </div>

          <textarea
            value={inputText}
            onChange={(e) => setInputText(e.target.value)}
            placeholder="Paste mixed emails here..."
            className="flex-grow w-full p-4 bg-gray-900/50 border border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 text-sm font-mono text-gray-300 custom-scrollbar mb-4"
            disabled={isProcessing}
          />

          <div className="flex gap-3">
            {isProcessing ? (
              <>
                <button onClick={() => { setIsPaused(!isPaused); controlRef.current.isPaused = !isPaused; }} className="flex-1 py-2 bg-yellow-600 text-white rounded-lg font-bold flex items-center justify-center gap-2">
                   {isPaused ? <PlayIcon className="w-4 h-4" /> : <PauseIcon className="w-4 h-4" />}
                   {isPaused ? 'Resume' : 'Pause'}
                </button>
                <button onClick={() => controlRef.current.shouldStop = true} className="flex-1 py-2 bg-red-600 text-white rounded-lg font-bold flex items-center justify-center gap-2">
                   <StopIcon className="w-4 h-4" /> Stop
                </button>
              </>
            ) : (
              <button
                onClick={processEmails}
                disabled={!inputText.trim()}
                className="w-full py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-bold shadow-lg disabled:opacity-50"
              >
                Sort & Validate
              </button>
            )}
          </div>

          {progress && (
            <div className="mt-4">
              <div className="flex justify-between text-xs text-blue-300 mb-1">
                <span>Processing batches...</span>
                <span>{Math.round((progress.current / progress.total) * 100)}%</span>
              </div>
              <div className="w-full bg-gray-700 rounded-full h-1.5">
                <div className="bg-blue-500 h-1.5 rounded-full" style={{ width: `${(progress.current / progress.total) * 100}%` }} />
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="lg:col-span-8 flex flex-col h-full">
        <div className="bg-gray-800/40 backdrop-blur-md border border-gray-700 rounded-xl shadow-2xl flex flex-col h-[80vh]">
          <div className="p-5 border-b border-gray-700/50 bg-gray-800/30 flex justify-between items-center">
            <h2 className="text-xl font-bold text-white">Sorted Buckets</h2>
            {results.some(r => r.emails.length > 0) && (
              <button onClick={handleExportZip} className="flex items-center px-3 py-1.5 bg-green-600 hover:bg-green-700 text-white rounded text-xs font-bold transition-all">
                <FolderOpenIcon className="w-4 h-4 mr-2" /> Export ZIP
              </button>
            )}
          </div>
          <div className="flex-grow overflow-y-auto p-4 custom-scrollbar bg-gray-900/20">
            {results.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-full text-gray-500 opacity-40">
                <ShieldCheckIcon className="w-16 h-16 mb-4" />
                <p>Results will be categorized here</p>
              </div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {results.map((res) => (
                  <div key={res.category} className={`border rounded-xl p-4 transition-all ${res.emails.length > 0 ? 'bg-gray-800/60 border-gray-600' : 'bg-gray-900/40 border-gray-800 opacity-50'}`}>
                    <div className="flex justify-between items-center mb-3">
                      <div className="flex items-center gap-2">
                        {res.category === 'Professional' && <CheckIcon className="w-4 h-4 text-green-400" />}
                        {res.category === 'Invalid' && <XCircleIcon className="w-4 h-4 text-red-400" />}
                        <h3 className="font-bold text-white text-sm">{res.category}</h3>
                      </div>
                      <span className="text-xs bg-gray-900 px-2 py-0.5 rounded-full text-gray-400">{res.emails.length}</span>
                    </div>
                    <div className="h-32 overflow-y-auto font-mono text-[10px] text-gray-400 bg-gray-900/50 p-2 rounded-lg custom-scrollbar">
                      {res.emails.slice(0, 100).map((e, i) => <div key={i} className="truncate">{e}</div>)}
                      {res.emails.length > 100 && <div className="italic text-center py-1">... + {res.emails.length - 100} more</div>}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default EmailValidator;

import React, { useState, useCallback, useRef, useEffect } from 'react';
import type { ExtractedEmail } from './types';
import CountrySelector from './components/CountrySelector';
import ResultsDisplay from './components/ResultsDisplay';
import EmailSorter from './components/EmailSorter';
import EmailAnalyzer from './components/EmailAnalyzer';
import EmailValidator from './components/EmailValidator';
import MXSorter from './components/MXSorter';
import SettingsModal from './components/SettingsModal';
import { findAndExtractEmails, suggestKeywords, generateDeepSearchPlan, analyzeCompanyFromEmail, setGlobalApiKey } from './services/geminiService';
import SparklesIcon from './components/icons/SparklesIcon';
import MagnifyingGlassIcon from './components/icons/MagnifyingGlassIcon';
import LinkIcon from './components/icons/LinkIcon';
import DocumentArrowUpIcon from './components/icons/DocumentArrowUpIcon';
import LightbulbIcon from './components/icons/LightbulbIcon';
import ToggleSwitch from './components/ToggleSwitch';
import XCircleIcon from './components/icons/XCircleIcon';
import BuildingOfficeIcon from './components/icons/BuildingOfficeIcon';
import FolderOpenIcon from './components/icons/FolderOpenIcon';
import ListBulletIcon from './components/icons/ListBulletIcon';
import Cog6ToothIcon from './components/icons/Cog6ToothIcon';
import BriefcaseIcon from './components/icons/BriefcaseIcon';
import ShieldCheckIcon from './components/icons/ShieldCheckIcon';
import ArrowsRightLeftIcon from './components/icons/ArrowsRightLeftIcon';


const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'extractor' | 'sorter' | 'analyzer' | 'validator' | 'mx-sorter'>('extractor');

  // Extractor State
  const [country, setCountry] = useState<string>('');
  const [keywords, setKeywords] = useState<string>('');
  const [sourceEmail, setSourceEmail] = useState<string>('');
  const [industry, setIndustry] = useState<string>('');
  const [companySize, setCompanySize] = useState<string>('');
  const [urls, setUrls] = useState<string>('');
  const [results, setResults] = useState<ExtractedEmail[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isSuggesting, setIsSuggesting] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [isDeepSearch, setIsDeepSearch] = useState<boolean>(false);
  const [verifyDomains, setVerifyDomains] = useState<boolean>(false);
  const [progressMessage, setProgressMessage] = useState<string | null>(null);

  // Settings State
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const stopSearchRef = useRef(false);

  const [toast, setToast] = useState<{ message: string; visible: boolean }>({ message: '', visible: false });

  // Init API Key from storage
  useEffect(() => {
    const storedKey = localStorage.getItem('gemini_api_key');
    if (storedKey) {
      setGlobalApiKey(storedKey);
    }
  }, []);

  const handleSaveApiKey = (key: string) => {
    if (key) {
      localStorage.setItem('gemini_api_key', key);
      setGlobalApiKey(key);
      showToast("API Key updated successfully.");
    } else {
      localStorage.removeItem('gemini_api_key');
      setGlobalApiKey('');
      showToast("API Key cleared. Using default if available.");
    }
  };

  const showToast = (message: string) => {
    setToast({ message, visible: true });
    setTimeout(() => {
      setToast({ message: '', visible: false });
    }, 4000);
  };

  const handleStopSearch = () => {
    stopSearchRef.current = true;
  };

  const executeSearch = async (searchKeywords: string) => {
     try {
      if (isDeepSearch) {
        setProgressMessage("Phase 1: Generating deep search plan...");
        const searchPlan = await generateDeepSearchPlan(searchKeywords, country, industry);

        let totalNewEmails = 0;

        for (let i = 0; i < searchPlan.length; i++) {
          if (stopSearchRef.current) {
            showToast("Deep search stopped by user.");
            break;
          }
          const subKeyword = searchPlan[i];
          setProgressMessage(`Phase 2 (${i + 1}/${searchPlan.length}): Searching for "${subKeyword}"...`);

          const extracted = await findAndExtractEmails(subKeyword, country, industry, companySize, '', verifyDomains);

          setResults(prevResults => {
            const existingEmails = new Set(prevResults.map(r => r.email));
            const newUniqueEmails = extracted.filter(email => !existingEmails.has(email.email));
            totalNewEmails += newUniqueEmails.length;
            return [...prevResults, ...newUniqueEmails];
          });
        }
        showToast(`Deep search complete! Found ${totalNewEmails} new emails.`);

      } else {
        setProgressMessage("Searching for companies and extracting emails...");
        const extractedEmails = await findAndExtractEmails(searchKeywords, country, industry, companySize, urls, verifyDomains);

        const existingEmails = new Set(results.map(r => r.email));
        const newUniqueEmails = extractedEmails.filter(email => !existingEmails.has(email.email));
        const duplicateCount = extractedEmails.length - newUniqueEmails.length;

        setResults(prevResults => [...prevResults, ...newUniqueEmails]);

        let toastMessage = '';
        if (newUniqueEmails.length === 0) {
          toastMessage = duplicateCount > 0 
            ? `Found ${duplicateCount} emails that are already in your list.` 
            : "No new emails found for the given criteria.";
        } else {
          toastMessage = `Successfully extracted ${newUniqueEmails.length} new emails!`;
          if (duplicateCount > 0) {
            toastMessage += ` (${duplicateCount} duplicates ignored.)`;
          }
        }
        showToast(toastMessage);
      }
    } catch (e: any) {
      setError(e.message || 'An unknown error occurred.');
      showToast("An error occurred during extraction.");
    }
  }

  const handleExtract = useCallback(async () => {
    if (isLoading) return;
    setError(null);
    setIsLoading(true);
    stopSearchRef.current = false;

    try {
        await executeSearch(keywords);
    } finally {
        setIsLoading(false);
        setProgressMessage(null);
    }
  }, [keywords, country, industry, companySize, urls, isLoading, results, isDeepSearch, verifyDomains]);

  const handleSimilarSearch = useCallback(async () => {
    if (isLoading || !sourceEmail) return;
    if (!country) {
        showToast("Please select a target country for the competitor search.");
        return;
    }

    setError(null);
    setIsLoading(true);
    stopSearchRef.current = false;

    try {
        setProgressMessage(`Analyzing company profile for ${sourceEmail}...`);
        const generatedQueries = await analyzeCompanyFromEmail(sourceEmail, country);

        if (generatedQueries.length > 0) {
            const newKeywords = generatedQueries.join('\n');
            setKeywords(newKeywords); // Update UI for visibility

            setProgressMessage("Company identified. Searching for similar businesses...");
            await executeSearch(newKeywords);
        } else {
            showToast("Could not identify similar companies. Please check the email.");
        }

    } catch (e: any) {
        setError(e.message || 'Failed to analyze email.');
        showToast("Error analyzing email.");
    } finally {
        setIsLoading(false);
        setProgressMessage(null);
    }

  }, [sourceEmail, country, isLoading, isDeepSearch, verifyDomains]);

  const handleClear = () => {
    setResults([]);
    setError(null);
    showToast("Results cleared.");
  };

  const handleSuggestKeywords = async () => {
    if (isSuggesting || !keywords.trim()) {
        showToast("Please enter some base keywords first.");
        return;
    };
    setIsSuggesting(true);
    try {
        const suggestions = await suggestKeywords(keywords);
        if (suggestions.length > 0) {
            const newKeywords = suggestions.join('\n');
            setKeywords(prev => `${prev}\n${newKeywords}`);
            showToast("AI has added new keyword suggestions!");
        } else {
            showToast("AI could not suggest new keywords at this time.");
        }
    } catch (e) {
        showToast("Failed to get keyword suggestions.");
    } finally {
        setIsSuggesting(false);
    }
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        const text = e.target?.result as string;
        setKeywords(text);
        showToast("Keywords loaded from file.");
      };
      reader.readAsText(file);
    }
  };

  const isUrlMode = urls.trim().length > 0;
  const isKeywordMode = !isUrlMode && !sourceEmail;
  const isSimilarMode = !isUrlMode && !!sourceEmail && keywords.trim().length === 0; 

  const renderContent = () => {
      switch(activeTab) {
          case 'sorter':
              return <EmailSorter showToast={showToast} />;
          case 'analyzer':
              return <EmailAnalyzer showToast={showToast} />;
          case 'validator':
              return <EmailValidator showToast={showToast} />;
          case 'mx-sorter':
              return <MXSorter showToast={showToast} />;
          default:
              return (
                <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                  {/* EXTRACTOR SIDEBAR */}
                  <div className="lg:col-span-3 bg-gray-800/50 backdrop-blur-sm border border-gray-700 rounded-xl shadow-2xl p-6 h-fit">
                    <h2 className="text-2xl font-bold text-white mb-4">Search Criteria</h2>

                    <div className="mb-6">
                      <label htmlFor="country" className="block text-sm font-medium text-gray-300 mb-1">Target Country (Required)</label>
                      <CountrySelector selectedCountry={country} setSelectedCountry={setCountry} disabled={isLoading} />
                    </div>

                    <div className="space-y-2 mb-6">
                      <ToggleSwitch 
                          label="Deep Search (High Volume)"
                          enabled={isDeepSearch}
                          onChange={setIsDeepSearch}
                          disabled={isLoading}
                        />
                        <ToggleSwitch 
                          label="Deep Website Search (Strict 'site:' Mode)"
                          enabled={verifyDomains}
                          onChange={setVerifyDomains}
                          disabled={isLoading}
                        />
                        <p className="text-xs text-gray-400 pl-1">Uses "site:domain.com" to find emails in sub-pages. Recommended for URL lists.</p>
                    </div>

                    <div className="space-y-6">
                      {/* METHOD 1: KEYWORDS */}
                      <div className={`p-4 border rounded-lg transition-all ${!isUrlMode && !sourceEmail ? 'border-blue-500/50 bg-gray-800' : 'border-gray-700 opacity-60'}`}>
                        <p className="font-semibold text-white mb-3 flex items-center"><MagnifyingGlassIcon className="w-4 h-4 mr-2"/> Find by Keywords</p>
                        <div className="space-y-4">
                          <div>
                            <label htmlFor="keywords" className="block text-sm font-medium text-gray-300 mb-1">Keywords (one per line)</label>
                            <textarea
                                id="keywords"
                                rows={3}
                                value={keywords}
                                onChange={(e) => setKeywords(e.target.value)}
                                placeholder="e.g., 'SaaS accounting software'"
                                disabled={isLoading || isUrlMode}
                                className="w-full px-3 py-2 bg-gray-700 border border-gray-600 rounded-md focus:ring-2 focus:ring-blue-500 transition disabled:cursor-not-allowed resize-y text-sm"
                            />
                            <div className="mt-2 flex items-center gap-2 flex-wrap">
                              <button onClick={() => fileInputRef.current?.click()} disabled={isLoading || isUrlMode} className="text-xs text-blue-400 hover:text-blue-300 flex items-center">
                                <DocumentArrowUpIcon className="w-3 h-3 mr-1" /> Load File
                              </button>
                              <input type="file" ref={fileInputRef} onChange={handleFileChange} accept=".txt" className="hidden" />
                              <button onClick={handleSuggestKeywords} disabled={isLoading || isUrlMode || isSuggesting} className="text-xs text-yellow-400 hover:text-yellow-300 flex items-center">
                                <LightbulbIcon className="w-3 h-3 mr-1" /> Suggest
                              </button>
                            </div>
                          </div>
                          <div className="grid grid-cols-2 gap-2">
                              <div>
                                  <input type="text" value={industry} onChange={(e) => setIndustry(e.target.value)} placeholder="Industry (Opt)" disabled={isLoading || isUrlMode} className="w-full px-2 py-1.5 bg-gray-700 border border-gray-600 rounded-md text-xs focus:ring-1 focus:ring-blue-500" />
                              </div>
                              <div>
                                  <input type="text" value={companySize} onChange={(e) => setCompanySize(e.target.value)} placeholder="Size (Opt)" disabled={isLoading || isUrlMode} className="w-full px-2 py-1.5 bg-gray-700 border border-gray-600 rounded-md text-xs focus:ring-1 focus:ring-blue-500" />
                              </div>
                          </div>
                          <button
                            onClick={handleExtract}
                            disabled={isLoading || !keywords.trim() || !country || isUrlMode}
                            className="w-full py-2 px-4 text-sm font-bold rounded-md bg-blue-600 hover:bg-blue-700 text-white shadow-lg transition-all disabled:opacity-50 disabled:cursor-not-allowed"
                          >
                            {isLoading && keywords.trim() ? 'Searching...' : 'Search Keywords'}
                          </button>
                        </div>
                      </div>

                      <div className="relative flex items-center"><div className="flex-grow border-t border-gray-600"></div><span className="flex-shrink mx-4 text-gray-500 text-xs font-bold">OR</span><div className="flex-grow border-t border-gray-600"></div></div>

                      {/* METHOD 2: SIMILAR COMPANIES */}
                      <div className={`p-4 border rounded-lg transition-all ${sourceEmail ? 'border-blue-500/50 bg-gray-800' : 'border-gray-700 opacity-60'}`}>
                        <p className="font-semibold text-white mb-3 flex items-center"><BuildingOfficeIcon className="w-4 h-4 mr-2"/> Find Similar Companies</p>
                        <div className="space-y-3">
                          <div>
                              <label htmlFor="sourceEmail" className="block text-sm font-medium text-gray-300 mb-1">Company Email</label>
                              <input 
                                  type="text" 
                                  id="sourceEmail" 
                                  value={sourceEmail} 
                                  onChange={(e) => setSourceEmail(e.target.value)} 
                                  placeholder="contact@competitor.com" 
                                  disabled={isLoading}
                                  className="w-full px-3 py-2 bg-gray-700 border border-gray-600 rounded-md focus:ring-2 focus:ring-blue-500 transition text-sm" 
                              />
                          </div>
                          <button
                            onClick={handleSimilarSearch}
                            disabled={isLoading || !sourceEmail.includes('@') || !country}
                            className="w-full py-2 px-4 text-sm font-bold rounded-md bg-teal-600 hover:bg-teal-700 text-white shadow-lg transition-all disabled:opacity-50 disabled:cursor-not-allowed"
                          >
                            {isLoading && sourceEmail ? 'Analyzing...' : 'Analyze & Find Similar'}
                          </button>
                        </div>
                      </div>

                      <div className="relative flex items-center"><div className="flex-grow border-t border-gray-600"></div><span className="flex-shrink mx-4 text-gray-500 text-xs font-bold">OR</span><div className="flex-grow border-t border-gray-600"></div></div>

                      {/* METHOD 3: URLs */}
                      <div className={`p-4 border rounded-lg transition-all ${isUrlMode ? 'border-blue-500/50 bg-gray-800' : 'border-gray-700 opacity-60'}`}>
                        <p className="font-semibold text-white mb-3 flex items-center"><LinkIcon className="w-4 h-4 mr-2"/> Extract from URLs</p>
                        <div>
                          <textarea id="urls" rows={3} value={urls} onChange={(e) => setUrls(e.target.value)} placeholder="https://example.com" className="w-full px-3 py-2 bg-gray-700 border border-gray-600 rounded-md focus:ring-2 focus:ring-blue-500 transition resize-y text-sm" disabled={isLoading}/>
                          <button
                            onClick={handleExtract}
                            disabled={isLoading || !isUrlMode}
                            className="w-full mt-3 py-2 px-4 text-sm font-bold rounded-md bg-indigo-600 hover:bg-indigo-700 text-white shadow-lg transition-all disabled:opacity-50 disabled:cursor-not-allowed"
                          >
                            Extract from URLs
                          </button>
                        </div>
                      </div>

                      {isLoading && (
                            <button onClick={handleStopSearch} className="w-full flex items-center justify-center py-2 px-4 text-sm font-bold rounded-md bg-red-600/80 hover:bg-red-600 text-white shadow-lg transition-all border border-red-500">
                              <XCircleIcon className="w-4 h-4 mr-2" /> Stop Search
                            </button>
                      )}
                    </div>
                  </div>

                  {/* EXTRACTOR RESULTS */}
                  <div className="lg:col-span-9">
                    <ResultsDisplay results={results} isLoading={isLoading} error={error} progressMessage={progressMessage} onClearResults={handleClear} />
                  </div>
                </div>
              );
      }
  }

  return (
    <>
      <div className={`fixed top-5 right-5 bg-blue-600 text-white px-4 py-2 rounded-lg shadow-lg transition-transform duration-300 z-[110] ${toast.visible ? 'translate-x-0' : 'translate-x-full'}`} style={{ transform: toast.visible ? 'translateX(0)' : 'translateX(calc(100% + 20px))' }}>
        {toast.message}
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        onSave={handleSaveApiKey} 
      />

      <div className="min-h-screen w-full bg-gray-900 text-white p-4 sm:p-6 lg:p-8 font-sans">
        <div className="max-w-[98%] mx-auto">
          <header className="text-center mb-8 relative">
            <div className="absolute right-0 top-0">
                <button 
                    onClick={() => setIsSettingsOpen(true)}
                    className="p-2 rounded-full text-gray-400 hover:text-white hover:bg-gray-800 transition"
                    title="Settings"
                >
                    <Cog6ToothIcon className="w-6 h-6" />
                </button>
            </div>
            <div className="inline-flex items-center justify-center">
                <SparklesIcon className="w-10 h-10 text-blue-400" />
                <h1 className="text-4xl sm:text-5xl font-extrabold ml-3 bg-clip-text text-transparent bg-gradient-to-r from-blue-400 to-teal-300">
                AI Email Extractor Pro
                </h1>
            </div>
            <p className="mt-2 max-w-2xl mx-auto text-lg text-gray-400">
              Intelligent email discovery and organization powered by Gemini.
            </p>
          </header>

          {/* TABS NAVIGATION */}
          <div className="flex justify-center mb-8 flex-wrap gap-2">
             <div className="bg-gray-800/50 p-1 rounded-xl inline-flex shadow-xl border border-gray-700 flex-wrap justify-center">
                <button
                  onClick={() => setActiveTab('extractor')}
                  className={`flex items-center px-6 py-2.5 rounded-lg text-sm font-bold transition-all duration-200 ${
                    activeTab === 'extractor' 
                    ? 'bg-blue-600 text-white shadow-md' 
                    : 'text-gray-400 hover:text-white hover:bg-gray-700/50'
                  }`}
                >
                  <ListBulletIcon className="w-4 h-4 mr-2" />
                  Extractor
                </button>
                <button
                  onClick={() => setActiveTab('sorter')}
                  className={`flex items-center px-6 py-2.5 rounded-lg text-sm font-bold transition-all duration-200 ${
                    activeTab === 'sorter' 
                    ? 'bg-blue-600 text-white shadow-md' 
                    : 'text-gray-400 hover:text-white hover:bg-gray-700/50'
                  }`}
                >
                  <FolderOpenIcon className="w-4 h-4 mr-2" />
                  Country Sorter
                </button>
                <button
                  onClick={() => setActiveTab('analyzer')}
                  className={`flex items-center px-6 py-2.5 rounded-lg text-sm font-bold transition-all duration-200 ${
                    activeTab === 'analyzer' 
                    ? 'bg-purple-600 text-white shadow-md' 
                    : 'text-gray-400 hover:text-white hover:bg-gray-700/50'
                  }`}
                >
                  <BriefcaseIcon className="w-4 h-4 mr-2" />
                  Industry Analyzer
                </button>
                <button
                  onClick={() => setActiveTab('validator')}
                  className={`flex items-center px-6 py-2.5 rounded-lg text-sm font-bold transition-all duration-200 ${
                    activeTab === 'validator' 
                    ? 'bg-orange-600 text-white shadow-md' 
                    : 'text-gray-400 hover:text-white hover:bg-gray-700/50'
                  }`}
                >
                  <ShieldCheckIcon className="w-4 h-4 mr-2" />
                  Sorter & Validator
                </button>
                <button
                  onClick={() => setActiveTab('mx-sorter')}
                  className={`flex items-center px-6 py-2.5 rounded-lg text-sm font-bold transition-all duration-200 ${
                    activeTab === 'mx-sorter' 
                    ? 'bg-blue-800 text-white shadow-md' 
                    : 'text-gray-400 hover:text-white hover:bg-gray-700/50'
                  }`}
                >
                  <ArrowsRightLeftIcon className="w-4 h-4 mr-2" />
                  MX Sorter
                </button>
             </div>
          </div>

          <main>
             {renderContent()}
          </main>
        </div>
      </div>
    </>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import DocumentArrowUpIcon from './icons/DocumentArrowUpIcon';
import FolderOpenIcon from './icons/FolderOpenIcon';
import ArrowPathIcon from './icons/ArrowPathIcon';
import ShieldCheckIcon from './icons/ShieldCheckIcon';
import XCircleIcon from './icons/XCircleIcon';
import CheckIcon from './icons/CheckIcon';
import PauseIcon from './icons/PauseIcon';
import PlayIcon from './icons/PlayIcon';
import StopIcon from './icons/StopIcon';
import ToggleSwitch from './ToggleSwitch';
import JSZip from 'jszip';
import { GoogleGenAI, Type } from "@google/genai";

interface EmailValidatorProps {
  showToast: (msg: string) => void;
}

interface ValidationResult {
  category: 'Professional' | 'Public' | 'Gov/Edu' | 'Financial' | 'Disposable' | 'Invalid';
  emails: string[];
}

const PUBLIC_DOMAINS = new Set([
  'gmail.com', 'googlemail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'live.com', 'msn.com',
  'aol.com', 'icloud.com', 'me.com', 'protonmail.com', 'zoho.com', 'yandex.com', 'mail.com', 'gmx.com'
]);

const DISPOSABLE_DOMAINS = new Set([
  'temp-mail.org', 'guerrillamail.com', '10minutemail.com', 'mailinator.com', 'sharklasers.com'
]);

const FINANCIAL_KEYWORDS = ['bank', 'credit', 'capital', 'finance', 'invest', 'trading', 'wealth', 'pay', 'crypto', 'wallet'];

const EmailValidator: React.FC<EmailValidatorProps> = ({ showToast }) => {
  const [inputText, setInputText] = useState('');
  const [results, setResults] = useState<ValidationResult[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [useOnlineMode, setUseOnlineMode] = useState(false);
  const [progress, setProgress] = useState<{ current: number; total: number } | null>(null);

  const controlRef = useRef({ shouldStop: false, isPaused: false });

  const classifyEmailOffline = (email: string): ValidationResult['category'] => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) return 'Invalid';

    const [user, domain] = email.toLowerCase().split('@');
    const parts = domain.split('.');
    const tld = parts[parts.length - 1];

    if (DISPOSABLE_DOMAINS.has(domain)) return 'Disposable';
    if (PUBLIC_DOMAINS.has(domain)) return 'Public';
    if (tld === 'gov' || tld === 'edu' || domain.includes('.edu.') || domain.includes('.gov.')) return 'Gov/Edu';
    if (FINANCIAL_KEYWORDS.some(kw => domain.includes(kw))) return 'Financial';

    // Heuristic for "Fake" usernames: high number count or random chars
    const numCount = (user.match(/\d/g) || []).length;
    if (numCount > 5 || user.length > 15 && !user.includes('.') && !user.includes('_')) {
        // We could put these in "Disposable" or "Invalid", but for this tool let's call it professional unless TLD is weird
    }

    return 'Professional';
  };

  const classifyDomainsOnline = async (domains: string[]): Promise<Map<string, ValidationResult['category']>> => {
    // Correctly initialize GoogleGenAI with the API key from environment variables as per requirements.
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `Classify these business domains into categories: Professional, Gov/Edu, or Financial. 
    Professional: standard corporate domains.
    Gov/Edu: Government or Educational institutions.
    Financial: Banks, Investment firms.

    Domains: ${domains.join(', ')}

    Return ONLY a JSON object where keys are domains and values are the categories.`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          description: "Map of domain to category",
          properties: domains.reduce((acc: any, d) => {
            acc[d] = { type: Type.STRING };
            return acc;
          }, {})
        }
      }
    });

    try {
        // Directly accessing the .text property of GenerateContentResponse as per updated guidelines.
        const responseText = response.text || '{}';
        const data = JSON.parse(responseText);
        const map = new Map<string, ValidationResult['category']>();
        Object.entries(data).forEach(([d, cat]) => {
            map.set(d, cat as ValidationResult['category']);
        });
        return map;
    } catch (e) {
        console.error("Online classification failed", e);
        return new Map();
    }
  };

  const processEmails = async () => {
    if (!inputText.trim()) {
      showToast("Please enter emails to process.");
      return;
    }

    setIsProcessing(true);
    setIsPaused(false);
    controlRef.current = { shouldStop: false, isPaused: false };

    const rawEmails = inputText.split(/[\s,;]+/).map(e => e.trim()).filter(Boolean);
    const uniqueEmails: string[] = Array.from(new Set(rawEmails));
    const total = uniqueEmails.length;

    const categoryMap: Record<ValidationResult['category'], string[]> = {
      Professional: [], Public: [], 'Gov/Edu': [], Financial: [], Disposable: [], Invalid: []
    };

    const needsOnline: string[] = [];
    const domainToEmails = new Map<string, string[]>();

    // Phase 1: Offline Classification
    // Fix: Explicitly typing 'email' as string to resolve TS unknown errors
    uniqueEmails.forEach((email: string) => {
      const cat = classifyEmailOffline(email);
      if (useOnlineMode && cat === 'Professional') {
          const domain = email.split('@')[1]?.toLowerCase();
          if (domain) {
              if (!domainToEmails.has(domain)) {
                  domainToEmails.set(domain, []);
                  needsOnline.push(domain);
              }
              domainToEmails.get(domain)!.push(email);
          }
      } else {
          categoryMap[cat].push(email);
      }
    });

    // Phase 2: Online Classification (Batched)
    if (useOnlineMode && needsOnline.length > 0) {
        const BATCH_SIZE = 30;
        for (let i = 0; i < needsOnline.length; i += BATCH_SIZE) {
            if (controlRef.current.shouldStop) break;
            while (controlRef.current.isPaused) await new Promise(r => setTimeout(r, 200));

            const batch = needsOnline.slice(i, i + BATCH_SIZE);
            setProgress({ current: i, total: needsOnline.length });

            try {
                const onlineResults = await classifyDomainsOnline(batch);
                batch.forEach(domain => {
                    const cat = onlineResults.get(domain) || 'Professional';
                    const emails = domainToEmails.get(domain) || [];
                    if (categoryMap[cat]) categoryMap[cat].push(...emails);
                    else categoryMap['Professional'].push(...emails);
                });
            } catch (e) {
                batch.forEach(domain => {
                    categoryMap['Professional'].push(...(domainToEmails.get(domain) || []));
                });
            }
        }
    }

    setResults(Object.entries(categoryMap).map(([category, emails]) => ({
      category: category as ValidationResult['category'],
      emails
    })));

    setIsProcessing(false);
    setProgress(null);
    showToast(`Validation complete. ${uniqueEmails.length} emails sorted.`);
  };

  const handleExportZip = async () => {
    const zip = new JSZip();
    results.forEach(res => {
      if (res.emails.length > 0) {
        zip.file(`${res.category.replace('/', '_')}_Emails.txt`, res.emails.join('\n'));
      }
    });
    const blob = await zip.generateAsync({ type: 'blob' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Validated_Emails_${new Date().getTime()}.zip`;
    a.click();
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 h-full">
      <div className="lg:col-span-4 flex flex-col h-full space-y-4">
        <div className="bg-gray-800/50 backdrop-blur-sm border border-gray-700 rounded-xl shadow-2xl p-6 flex-grow flex flex-col">
          <div className="mb-4">
            <h2 className="text-2xl font-bold text-white flex items-center gap-2">
              <ShieldCheckIcon className="w-6 h-6 text-blue-400" />
              Sorter & Validator
            </h2>
            <div className="mt-4 space-y-2">
                <ToggleSwitch 
                  label="AI Enhancement (Online)" 
                  enabled={useOnlineMode} 
                  onChange={setUseOnlineMode} 
                  disabled={isProcessing}
                />
                <p className="text-gray-400 text-xs">
                  {useOnlineMode 
                    ? "Deep classification of business vs. finance vs. gov using AI." 
                    : "Fast regex/list-based sorting. Zero API cost."}
                </p>
            </div>
          </div>

          <textarea
            value={inputText}
            onChange={(e) => setInputText(e.target.value)}
            placeholder="Paste mixed emails here..."
            className="flex-grow w-full p-4 bg-gray-900/50 border border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 text-sm font-mono text-gray-300 custom-scrollbar mb-4"
            disabled={isProcessing}
          />

          <div className="flex gap-3">
            {isProcessing ? (
              <>
                <button onClick={() => { setIsPaused(!isPaused); controlRef.current.isPaused = !isPaused; }} className="flex-1 py-2 bg-yellow-600 text-white rounded-lg font-bold flex items-center justify-center gap-2">
                   {isPaused ? <PlayIcon className="w-4 h-4" /> : <PauseIcon className="w-4 h-4" />}
                   {isPaused ? 'Resume' : 'Pause'}
                </button>
                <button onClick={() => controlRef.current.shouldStop = true} className="flex-1 py-2 bg-red-600 text-white rounded-lg font-bold flex items-center justify-center gap-2">
                   <StopIcon className="w-4 h-4" /> Stop
                </button>
              </>
            ) : (
              <button
                onClick={processEmails}
                disabled={!inputText.trim()}
                className="w-full py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-bold shadow-lg disabled:opacity-50"
              >
                Sort & Validate
              </button>
            )}
          </div>

          {progress && (
            <div className="mt-4">
              <div className="flex justify-between text-xs text-blue-300 mb-1">
                <span>Processing batches...</span>
                <span>{Math.round((progress.current / progress.total) * 100)}%</span>
              </div>
              <div className="w-full bg-gray-700 rounded-full h-1.5">
                <div className="bg-blue-500 h-1.5 rounded-full" style={{ width: `${(progress.current / progress.total) * 100}%` }} />
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="lg:col-span-8 flex flex-col h-full">
        <div className="bg-gray-800/40 backdrop-blur-md border border-gray-700 rounded-xl shadow-2xl flex flex-col h-[80vh]">
          <div className="p-5 border-b border-gray-700/50 bg-gray-800/30 flex justify-between items-center">
            <h2 className="text-xl font-bold text-white">Sorted Buckets</h2>
            {results.some(r => r.emails.length > 0) && (
              <button onClick={handleExportZip} className="flex items-center px-3 py-1.5 bg-green-600 hover:bg-green-700 text-white rounded text-xs font-bold transition-all">
                <FolderOpenIcon className="w-4 h-4 mr-2" /> Export ZIP
              </button>
            )}
          </div>
          <div className="flex-grow overflow-y-auto p-4 custom-scrollbar bg-gray-900/20">
            {results.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-full text-gray-500 opacity-40">
                <ShieldCheckIcon className="w-16 h-16 mb-4" />
                <p>Results will be categorized here</p>
              </div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {results.map((res) => (
                  <div key={res.category} className={`border rounded-xl p-4 transition-all ${res.emails.length > 0 ? 'bg-gray-800/60 border-gray-600' : 'bg-gray-900/40 border-gray-800 opacity-50'}`}>
                    <div className="flex justify-between items-center mb-3">
                      <div className="flex items-center gap-2">
                        {res.category === 'Professional' && <CheckIcon className="w-4 h-4 text-green-400" />}
                        {res.category === 'Invalid' && <XCircleIcon className="w-4 h-4 text-red-400" />}
                        <h3 className="font-bold text-white text-sm">{res.category}</h3>
                      </div>
                      <span className="text-xs bg-gray-900 px-2 py-0.5 rounded-full text-gray-400">{res.emails.length}</span>
                    </div>
                    <div className="h-32 overflow-y-auto font-mono text-[10px] text-gray-400 bg-gray-900/50 p-2 rounded-lg custom-scrollbar">
                      {res.emails.slice(0, 100).map((e, i) => <div key={i} className="truncate">{e}</div>)}
                      {res.emails.length > 100 && <div className="italic text-center py-1">... + {res.emails.length - 100} more</div>}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default EmailValidator;
